//! Pre-written illustrative text. Not generated by any model.

use crate::{ProviderId, Task};

pub(crate) fn text(provider: ProviderId, task: Task) -> String {
    let view = match provider {
        ProviderId::Openai => {
            "Define the outcome, stakeholders and boundaries. Document architectural options and the decision criteria."
        }
        ProviderId::Anthropic => {
            "Break the work into small deliverables. Specify completion criteria, dependencies and a review checklist."
        }
        ProviderId::Gemini => {
            "Identify missing evidence, research questions and validation methods. Record assumptions and sources."
        }
        ProviderId::Xai => {
            "Challenge the assumptions, consider alternatives and record the strongest counterarguments."
        }
    };
    format!(
        "Illustrative fixture — not generated by a live AI model.\n\n{}\n\n{} perspective: {}\n\nNext: confirm the brief and nominate a human reviewer.",
        task.instruction(),
        provider.perspective(),
        view
    )
}
